import{_ as l,C as r,c as s,o as n,ae as i,j as e,G as a,w as g,a as u}from"./chunks/framework.DsCIUHsX.js";const f=JSON.parse('{"title":"ZBC 服务器游玩条例","description":"","frontmatter":{},"headers":[],"relativePath":"Rules.md","filePath":"Rules.md"}'),c={name:"Rules.md"};function d(h,o,b,p,q,_){const t=r("font");return n(),s("div",null,[o[1]||(o[1]=i('<h1 id="zbc-服务器游玩条例" tabindex="-1">ZBC 服务器游玩条例 <a class="header-anchor" href="#zbc-服务器游玩条例" aria-label="Permalink to &quot;ZBC 服务器游玩条例&quot;">​</a></h1><h2 id="沟通交流条约" tabindex="-1">沟通交流条约 <a class="header-anchor" href="#沟通交流条约" aria-label="Permalink to &quot;沟通交流条约&quot;">​</a></h2><blockquote><p>此条目适用于服务器和QQ群</p></blockquote><ul><li><strong>禁止发表不当言论</strong>（如：涉政、涉黄、人身攻击等）。 <ul><li><strong>第一次违规</strong>：禁言 30 分钟</li><li><strong>之后每次违规</strong>：增加 30 分钟禁言时间</li></ul></li><li><strong>争执处理</strong>：若游戏内聊天发生争执，<strong>请保存聊天记录</strong>，管理员将根据情况判断。</li><li><strong>邀请规则</strong>：邀请机器人、广告、兼职等用户入群，将连同邀请人一并移除并拉入黑名单。</li></ul><h2 id="假人管理条例" tabindex="-1">假人管理条例 <a class="header-anchor" href="#假人管理条例" aria-label="Permalink to &quot;假人管理条例&quot;">​</a></h2><blockquote><p>此条目适用于服务器</p></blockquote><ul><li><strong>假人使用时间</strong>：23:00 至次日 9:00 <ul><li>召唤假人时请更改名字为 <code>ID+用途</code>（如：<code>zhaQvQ_ShuaSha</code>）。</li><li><strong>不建议召唤多个假人</strong>，避免影响服务器体验。</li></ul></li><li><strong>违规处理</strong>： <ul><li><strong>第一次违规</strong>：禁用 24 小时</li><li><strong>第二次违规</strong>：禁用 72 小时</li><li><strong>第三次违规</strong>：禁用一周</li><li><strong>继续违规</strong>：酌情<strong>永久封禁</strong></li></ul></li></ul><h2 id="机器使用条例" tabindex="-1">机器使用条例 <a class="header-anchor" href="#机器使用条例" aria-label="Permalink to &quot;机器使用条例&quot;">​</a></h2><blockquote><p>此条目适用于服务器</p></blockquote><ul><li><strong>卡顿限制</strong>：当 <strong>tps 低于 15</strong> 或 <strong>人数超过 15</strong> 时，禁止使用高卡顿机器（如四门+猪人塔、守卫者农场、苔藓机等）。</li><li><strong>挂机时间限制</strong>： <ul><li><strong>低卡顿机器</strong>：不推荐挂机超过 <strong>6 小时</strong></li><li><strong>高卡顿机器</strong>：不推荐挂机超过 <strong>15 分钟</strong></li></ul></li><li><strong>违规处理</strong>： <ul><li><strong>第一次违规</strong>：禁用 24 小时</li><li><strong>第二次违规</strong>：禁用 72 小时</li><li><strong>第三次违规</strong>：禁用一周</li><li><strong>继续违规</strong>：酌情<strong>永久封禁</strong></li></ul></li></ul><h2 id="管理员管理条例" tabindex="-1">管理员管理条例 <a class="header-anchor" href="#管理员管理条例" aria-label="Permalink to &quot;管理员管理条例&quot;">​</a></h2><blockquote><p>此条目适用于服务器</p></blockquote><ul><li><strong>管理员行为</strong>：禁止管理员进行以下行为： <ul><li>开启创造、私自回档、包庇偏袒玩家、未经允许给予玩家物品</li><li>一旦发现，<strong>永久封禁</strong>。</li></ul></li><li><strong>管理员禁言/封禁玩家</strong>：管理员禁言或封禁玩家时，只需报告，无需审核。 <ul><li>如误封，请联系腐竹。</li></ul></li><li><strong>管理员违规处理</strong>：管理员违规同样适用以上条例。</li><li><strong>管理员权限</strong>： <ul><li>允许使用 <strong>观察者模式</strong> 监督玩家行为</li><li>允许使用 <strong>强制 TP 权限</strong></li></ul></li></ul><h2 id="举报和处理" tabindex="-1">举报和处理 <a class="header-anchor" href="#举报和处理" aria-label="Permalink to &quot;举报和处理&quot;">​</a></h2><blockquote><p>此条目适用于服务器</p></blockquote><ul><li><strong>举报流程</strong>：举报请私聊 <strong>腐竹</strong>，并提供详细过程和证据。 <ul><li><strong>优先处理</strong>：举报会在 24 小时内处理完毕。</li><li><strong>回档操作</strong>：在周末或寒暑假尽量 24 小时内完成，最长 48 小时。</li><li><strong>开学后处理时效</strong>：由于管理人员在线时间不定，处理时效可能顺延，感谢理解。</li></ul></li></ul><hr>',17)),e("blockquote",null,[a(t,{style:{color:"#117CEE"}},{default:g(()=>o[0]||(o[0]=[u("最后编辑于2024.5.26 学渣")])),_:1})])])}const m=l(c,[["render",d]]);export{f as __pageData,m as default};
